package tn.esprit.partnerintelligence.entity;
import jakarta.persistence.*;import java.time.Instant;@Entity public class InferenceAuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String requestType; private Long partnerId; private String modelName; private String promptVersion; private Integer latencyMs; private String outcomeStatus; private String traceId; @Column(columnDefinition="TEXT") private String inputDigest; @Column(columnDefinition="TEXT") private String outputDigest; private Instant createdAt=Instant.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getRequestType(){return requestType;} public void setRequestType(String requestType){this.requestType=requestType;} public Long getPartnerId(){return partnerId;} public void setPartnerId(Long partnerId){this.partnerId=partnerId;} public String getModelName(){return modelName;} public void setModelName(String modelName){this.modelName=modelName;} public String getPromptVersion(){return promptVersion;} public void setPromptVersion(String promptVersion){this.promptVersion=promptVersion;} public Integer getLatencyMs(){return latencyMs;} public void setLatencyMs(Integer latencyMs){this.latencyMs=latencyMs;} public String getOutcomeStatus(){return outcomeStatus;} public void setOutcomeStatus(String outcomeStatus){this.outcomeStatus=outcomeStatus;} public String getTraceId(){return traceId;} public void setTraceId(String traceId){this.traceId=traceId;} public String getInputDigest(){return inputDigest;} public void setInputDigest(String inputDigest){this.inputDigest=inputDigest;} public String getOutputDigest(){return outputDigest;} public void setOutputDigest(String outputDigest){this.outputDigest=outputDigest;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant createdAt){this.createdAt=createdAt;} }